            index: controller.index(),
            maxVisible: controller.getMaxVisible(),
            entryWidth: controller.getEntryWidth(),
            entries: controller.entries(),
          }),
          back: controller.back,
          forward: controller.forward,
        };
      } catch (error) {
        // diagnostics are optional
      }
    }
