      readLocation,
      resolvePanelLabel,
      resolveSessionLabel,
      entryKey,
      clampVisible,
      clampEntryWidth,
      MIN_VISIBLE,
      MAX_VISIBLE,
      DEFAULT_VISIBLE,
      MIN_ENTRY_WIDTH,
      MAX_ENTRY_WIDTH,
      DEFAULT_ENTRY_WIDTH,
      zh,
      en,
